package com.example.valtiva.data.local.entity

import androidx.room.ColumnInfo
import androidx.room.Entity
import androidx.room.PrimaryKey
import java.math.BigDecimal
import java.time.Instant
import java.time.LocalDate

/**
 * A conversion the user performed, as stored locally.
 *
 * Unlike [FavoriteExchangeEntity], this keeps the full outcome — both amounts, the rate and the
 * date it was published — because a history row has to represent a conversion that really
 * happened, not just the pair involved. [id] is autogenerated: nothing about a conversion is
 * naturally unique on its own (the same pair can be converted twice in the same millisecond), so a
 * surrogate key is the only reliable identity.
 */
@Entity(tableName = "conversion_history")
data class ConversionHistoryEntity(
  @PrimaryKey(autoGenerate = true)
  @ColumnInfo(name = "id")
  val id: Long = 0,
  @ColumnInfo(name = "source_amount") val sourceAmount: BigDecimal,
  @ColumnInfo(name = "base_currency") val baseCurrency: String,
  @ColumnInfo(name = "target_amount") val targetAmount: BigDecimal,
  @ColumnInfo(name = "quote_currency") val quoteCurrency: String,
  @ColumnInfo(name = "rate") val rate: BigDecimal,
  @ColumnInfo(name = "rate_date") val rateDate: LocalDate,
  @ColumnInfo(name = "timestamp") val timestamp: Instant,
)
